func main() {
	s := make([]int, 3, 5)
	s[0], s[1], s[2] = 1, 2, 3

	a := append(s, 4) // cap=5 足够，不扩容
	b := append(s, 5) // cap=5 足够，不扩容

	fmt.Println(a) // [1 2 3 5]  ← 不是 [1 2 3 4]
	fmt.Println(b) // [1 2 3 5]
	// a[3] 和 b[3] 写入了底层数组同一个位置，b 覆盖了 a
}

func f() (result int) {
	defer func() {
		result++  // defer 修改命名返回值
	}()
	return 0  // 先赋值 result=0，再执行 defer result++
}
// f() 返回 1，不是 0

func g() int {
	result := 0
	defer func() {
		result++  // 修改的是局部变量，不影响返回值
	}()
	return result  // 匿名返回值，return 时已拷贝
}
// g() 返回 0

// Go 1.21 及之前的经典陷阱
funcs := make([]func(), 3)
for i := 0; i < 3; i++ {
	funcs[i] = func() { fmt.Println(i) }
}
for _, f := range funcs {
	f() // 全部输出 3，不是 0 1 2
}

// 修复方式一：闭包传参
for i := 0; i < 3; i++ {
	i := i // 重新声明，每次迭代独立副本
	funcs[i] = func() { fmt.Println(i) }
}

// Go 1.22+：默认每次迭代创建新变量，无需手动修复

type Bad struct {
	a bool   // 1 byte + 7 padding
	b int64  // 8 bytes
	c bool   // 1 byte + 7 padding
}
// sizeof(Bad) = 24

type Good struct {
	b int64  // 8 bytes
	a bool   // 1 byte
	c bool   // 1 byte + 6 padding
}
// sizeof(Good) = 16  节省 33%

// 标准转换（有内存拷贝）
s := "hello"
b := []byte(s)  // 拷贝
s2 := string(b) // 拷贝

// unsafe 零拷贝（Go 1.20+ 推荐方式）
import "unsafe"
func StringToBytes(s string) []byte {
	return unsafe.Slice(unsafe.StringData(s), len(s))
}
func BytesToString(b []byte) string {
	return unsafe.String(unsafe.SliceData(b), len(b))
}

//        | nil channel | closed channel
// -------|-------------|---------------
// read   | block       | zero value, false
// write  | block       | panic
// close  | panic       | panic

// select 中利用 nil channel 禁用分支
var ch1, ch2 <-chan int
ch1 = producer1()
ch2 = producer2()
for ch1 != nil || ch2 != nil {
	select {
	case v, ok := <-ch1:
		if !ok { ch1 = nil; continue } // 关闭后置 nil，禁用此 case
		process(v)
	case v, ok := <-ch2:
		if !ok { ch2 = nil; continue }
		process(v)
	}
}
